declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/health_network_v590.php';$u=hn590_require_login('/health-provider-signup.php');$flash='';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){try{csrf_check();$type=(string)($_POST['provider_type']??'');$name=trim((string)($_POST['name']??''));$phone=trim((string)($_POST['phone']??''));$address=trim((string)($_POST['address']??''));if(!in_array($type,['pharmacy','lab'],true)||$name===''||$phone===''||$address==='')throw new RuntimeException('Provider type, name, phone and address are required.');if($type==='pharmacy'){db()->prepare("INSERT INTO health_pharmacies_v590(tenant_id,owner_user_id,name,slug,phone,email,address,area,delivery_available,pickup_available,verified,featured,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,0,0,'pending',NOW(),NOW())")->execute([hn590_tid(),(int)$u['id'],$name,hn590_slug($name).'-'.(int)$u['id'],$phone,$u['email']??null,$address,trim((string)($_POST['area']??''))?:null,!empty($_POST['delivery'])?1:0,1]);}else{db()->prepare("INSERT INTO health_labs_v590(tenant_id,owner_user_id,name,slug,phone,email,address,area,home_collection,verified,featured,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,0,0,'pending',NOW(),NOW())")->execute([hn590_tid(),(int)$u['id'],$name,hn590_slug($name).'-'.(int)$u['id'],$phone,$u['email']??null,$address,trim((string)($_POST['area']??''))?:null,!empty($_POST['home_collection'])?1:0]);}$flash='Provider application submitted for admin verification.';}catch(Throwable $e){$error=$e->getMessage();}}hn590_public_header('Join Healthcare Network','Apply to list a pharmacy or diagnostic lab in the city healthcare network.');
?><main><section class="hn590-pagehero"><div class="hn590-shell"><span>PROVIDER ONBOARDING</span><h1>Join the ShahkotPK Healthcare Network.</h1><p>Pharmacies and diagnostic labs can submit an application. Public listing remains hidden until admin verification.</p></div></section><section class="hn590-section"><div class="hn590-shell" style="max-width:760px"><?php if($flash):?><div class="hn590-alert ok"><?=e($flash)?></div><?php endif;?><?php if($error):?><div class="hn590-alert err"><?=e($error)?></div><?php endif;?><section class="hn590-form-card"><h2>Provider application</h2><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><label>Provider type<select name="provider_type" required><option value="pharmacy">Pharmacy</option><option value="lab">Diagnostic Lab</option></select></label><label>Provider name<input name="name" required></label><label>Phone<input name="phone" required></label><label>Address<textarea name="address" required></textarea></label><label>Area<input name="area"></label><label class="check"><input type="checkbox" name="delivery"> Pharmacy delivery available</label><label class="check"><input type="checkbox" name="home_collection"> Lab home sample collection available</label><button class="hn590-btn primary">Submit for Verification</button></form><p class="hn590-warning">Submission does not imply verification, licensing approval or endorsement. Admin should validate provider credentials before activating the public listing.</p></section></div></section></main><?php hn590_public_footer();?>
